Here's the implementation using a straightforward tokenizer + recursive-descent parser over `fractions.Fraction`:

```python
import re
from fractions import Fraction


def fraction_expr(s: str) -> str:
    def tokenize(text):
        token_re = re.compile(r'\d+/\d+|\d+|[()+\-*]')
        tokens = []
        idx = 0
        n = len(text)
        while idx < n:
            c = text[idx]
            if c.isspace():
                idx += 1
                continue
            m = token_re.match(text, idx)
            if not m:
                raise ValueError(f"malformed expression: unexpected character {c!r}")
            tokens.append(m.group())
            idx = m.end()
        return tokens

    tokens = tokenize(s)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_atom():
        t = peek()
        if t == '(':
            advance()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("malformed expression: expected ')'")
            advance()
            return val
        elif t is not None and re.fullmatch(r'\d+(/\d+)?', t):
            advance()
            if '/' in t:
                num_s, den_s = t.split('/')
                num = int(num_s)
                den = int(den_s)
                if den == 0:
                    raise ValueError("zero denominator in fraction literal")
                return Fraction(num, den)
            else:
                return Fraction(int(t))
        else:
            raise ValueError("malformed expression: expected number or '('")

    def parse_factor():
        if peek() == '-':
            advance()
            val = parse_factor()
            return -val
        return parse_atom()

    def parse_term():
        val = parse_factor()
        while peek() == '*':
            advance()
            rhs = parse_factor()
            val *= rhs
        return val

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    if not tokens:
        raise ValueError("empty expression")

    result = parse_expr()

    if pos != len(tokens):
        raise ValueError("malformed expression: unexpected trailing tokens")

    if result.numerator == 0:
        return "0"
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"
```

This handles integers, `n/d` fraction literals, `+`, `-`, `*`, parentheses, and unary minus on terms, using `Fraction` for exact arithmetic and automatic reduction to lowest terms, while raising `ValueError` on malformed input or zero denominators.
